"use client";

import { type TanStackAutoFormApi, TanStackEngine, type TanStackFormOptions } from "../auto-form/adapters/tanstack";
import { AutoFormCore } from "../auto-form/auto-form-core";
import type { AutoFormProps as BaseAutoFormProps } from "../auto-form/types";

export type { ProtoformMessageCode, ProtoformMessageFormatter, ProtoformMessageParams } from "../../lib/core/messages";

type FormValues = Record<string, unknown>;

export type AutoFormProps<T extends FormValues = FormValues, TCustomFieldType extends string = never> = Omit<
  BaseAutoFormProps<T, TanStackAutoFormApi, TanStackFormOptions, never, TCustomFieldType>,
  "resolver"
>;

export type { TanStackAutoFormApi, TanStackFormOptions } from "../auto-form/adapters/tanstack";
export {
  type AutoFormAuditDiagnostic,
  type AutoFormAuditFormat,
  type AutoFormAuditReport,
  type AutoFormAuditTarget,
  auditAutoFormConfigurations,
  formatAutoFormAuditReport,
} from "../auto-form/audit";
export { ShadcnAutoFormFieldComponents } from "../auto-form/auto-form-core";
export {
  type CelEvaluation,
  type CompileCelExpressionOptions,
  type CompiledCelExpression,
  compileCelExpression,
  DEFAULT_CEL_MAX_COST,
} from "../auto-form/cel-runtime";
export {
  type AutoFormConfigurationDiagnostic,
  type AutoFormConfigurationDiagnosticCode,
  type AutoFormDiagnostic,
  type InspectAutoFormConfigurationInput,
  inspectAutoFormConfiguration,
} from "../auto-form/configuration";
export { useAutoForm } from "../auto-form/context";
export type { AutoFormFieldComponents, AutoFormFieldProps } from "../auto-form/core-types";
export type {
  DataProvider,
  DataProviderDefinition,
  DataProviderDependencyValues,
  DataProviderOption,
  DataProviderRegistration,
  DataProviderRegistry,
  DataProviderRequest,
  DataProviderResult,
  DataProviderStaleSelectionPolicy,
} from "../auto-form/data-providers";
export type { AutoFormEngineHandle } from "../auto-form/engine";
export { defaultRegistry } from "../auto-form/fields";
export { defaultClassifyField } from "../auto-form/helpers";
export {
  type FieldMatchContext,
  type FieldTypeDefinition,
  FieldTypeRegistry,
} from "../auto-form/registry";
export { AutoFormSlot } from "../auto-form/slot";
export type {
  AutoFormMode,
  AutoFormRevalidationMode,
  AutoFormRootHeaderMetadata,
  AutoFormRootHeaderMode,
  AutoFormStep,
  AutoFormStepperConfig,
  AutoFormStepperOrientation,
  AutoFormSubmitContext,
  AutoFormValidationMode,
  BuiltInFieldType,
  DeprecatedFieldPolicy,
  FieldTypes,
} from "../auto-form/types";

export function AutoForm<T extends FormValues = FormValues, TCustomFieldType extends string = never>({
  formOptions,
  ...props
}: AutoFormProps<T, TCustomFieldType>) {
  return (
    <AutoFormCore<T, TanStackAutoFormApi, TCustomFieldType>
      {...props}
      renderEngine={({ children, defaultValues, values }) => (
        <TanStackEngine
          defaultValues={defaultValues}
          formOptions={formOptions}
          onDirtyChange={props.onDirtyChange}
          values={values}
        >
          {children}
        </TanStackEngine>
      )}
    />
  );
}

"use client";

import {
  type FormAsyncValidateOrFn,
  type FormOptions,
  type FormValidateOrFn,
  type ReactFormExtendedApi,
  useForm,
  useSelector,
} from "@tanstack/react-form";
import React from "react";

import type { SchemaValidationError } from "../core-types";
import {
  type AutoFormArrayController,
  type AutoFormEngine,
  AutoFormEngineProvider,
  type AutoFormFieldController,
  errorMessages,
  useDirtyStateNotification,
} from "../engine";
import { getPathInObject } from "../field-utils";

type FormValues = Record<string, unknown>;
type SyncValidator = FormValidateOrFn<FormValues> | undefined;
type AsyncValidator = FormAsyncValidateOrFn<FormValues> | undefined;

export type TanStackFormOptions = FormOptions<
  FormValues,
  SyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  AsyncValidator,
  unknown
>;

export type TanStackAutoFormApi = ReactFormExtendedApi<
  FormValues,
  SyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  SyncValidator,
  AsyncValidator,
  AsyncValidator,
  unknown
>;

type TanStackSubmitPayload = Parameters<NonNullable<TanStackFormOptions["onSubmit"]>>[0];

interface TanStackEngineContextValue {
  clearFieldErrors: (name: string) => void;
  fieldErrors: Map<string, string[]>;
  form: TanStackAutoFormApi;
  registerRef: (name: string, element: HTMLElement | null) => void;
}

const TanStackEngineContext = React.createContext<TanStackEngineContextValue | null>(null);

function useTanStackEngineContext() {
  const context = React.useContext(TanStackEngineContext);
  if (!context) {
    throw new Error("TanStack AutoForm controls must be rendered inside the TanStack engine.");
  }
  return context;
}

function TanStackFieldController({
  children,
  name,
}: {
  children: (controller: AutoFormFieldController) => React.ReactNode;
  name: string;
}) {
  const { clearFieldErrors, fieldErrors, form, registerRef } = useTanStackEngineContext();

  return (
    <form.Field name={name}>
      {(field) => {
        const messages = [...errorMessages(field.state.meta.errors), ...(fieldErrors.get(name) ?? [])];
        return children({
          errors: [...new Set(messages)],
          name,
          onBlur: field.handleBlur,
          onChange: (value, options) => {
            clearFieldErrors(name);
            if (options) {
              form.setFieldValue(name, value, {
                dontUpdateMeta: options.shouldDirty === false && options.shouldTouch === false,
                dontValidate: options.shouldValidate === false,
              });
              return;
            }
            field.handleChange(value);
          },
          ref: (element) => registerRef(name, element),
          value: field.state.value,
        });
      }}
    </form.Field>
  );
}

function TanStackArrayController({
  children,
  name,
}: {
  children: (controller: AutoFormArrayController) => React.ReactNode;
  name: string;
}) {
  "use no memo";

  const { form } = useTanStackEngineContext();
  const value = useSelector(form.store, (state) => getPathInObject(state.values, name.split(".")));
  const arrayValue = Array.isArray(value) ? value : [];
  const collectionId = React.useId();
  const nextItemId = React.useRef(0);
  const keys = React.useRef<string[]>([]);

  React.useEffect(
    function syncArrayKeys() {
      while (keys.current.length < arrayValue.length) {
        nextItemId.current += 1;
        keys.current.push(`${collectionId}-${nextItemId.current}`);
      }
      if (keys.current.length > arrayValue.length) {
        keys.current.length = arrayValue.length;
      }
    },
    [arrayValue.length, collectionId]
  );

  return children({
    append: (item) => {
      nextItemId.current += 1;
      keys.current.push(`${collectionId}-${nextItemId.current}`);
      form.setFieldValue(name, [...arrayValue, item]);
    },
    items: arrayValue.map((item, index) => ({
      key: keys.current[index] ?? `auto-form-item-${index}`,
      value: item,
    })),
    remove: (index) => {
      keys.current.splice(index, 1);
      form.setFieldValue(
        name,
        arrayValue.filter((_, itemIndex) => itemIndex !== index)
      );
    },
  });
}

function setErrorAtPath(target: Record<string, unknown>, path: string[], messages: string[]) {
  let current = target;
  for (const [index, segment] of path.entries()) {
    if (index === path.length - 1) {
      current[segment] = { message: messages.join("\n") };
      return;
    }
    const existing = current[segment];
    if (existing && typeof existing === "object" && !Array.isArray(existing)) {
      current = existing as Record<string, unknown>;
      continue;
    }
    const nested: Record<string, unknown> = {};
    current[segment] = nested;
    current = nested;
  }
}

function validationErrorsByPath(errors: SchemaValidationError[]): Map<string, string[]> {
  const byPath = new Map<string, string[]>();
  for (const error of errors) {
    if (error.path.length === 0) {
      continue;
    }
    const path = error.path.join(".");
    byPath.set(path, [...(byPath.get(path) ?? []), error.message]);
  }
  return byPath;
}

function setDirtyAtPath(target: Record<string, unknown>, path: string[]) {
  let current = target;
  for (const [index, segment] of path.entries()) {
    if (index === path.length - 1) {
      current[segment] = true;
      return;
    }
    const existing = current[segment];
    if (existing && typeof existing === "object" && !Array.isArray(existing)) {
      current = existing as Record<string, unknown>;
    } else {
      const nested: Record<string, unknown> = {};
      current[segment] = nested;
      current = nested;
    }
  }
}

function dirtyFieldsFromMeta(fieldMeta: Record<string, { isDefaultValue?: boolean; isDirty?: boolean } | undefined>) {
  const dirtyFields: Record<string, unknown> = {};
  for (const [path, meta] of Object.entries(fieldMeta)) {
    if (meta?.isDirty && !meta.isDefaultValue) {
      setDirtyAtPath(dirtyFields, path.split("."));
    }
  }
  return dirtyFields;
}

function formValuesEqual(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) {
    return true;
  }
  if (!(left && right) || typeof left !== "object" || typeof right !== "object") {
    return false;
  }
  if (left instanceof Date && right instanceof Date) {
    return left.getTime() === right.getTime();
  }
  if (left instanceof Map && right instanceof Map) {
    if (left.size !== right.size) {
      return false;
    }
    return [...left].every(([key, value]) => right.has(key) && formValuesEqual(value, right.get(key)));
  }
  if (left instanceof Set && right instanceof Set) {
    return left.size === right.size && [...left].every((value) => right.has(value));
  }

  const leftRecord = left as Record<string, unknown>;
  const rightRecord = right as Record<string, unknown>;
  const leftKeys = Object.keys(leftRecord);
  const rightKeys = Object.keys(rightRecord);
  return (
    leftKeys.length === rightKeys.length &&
    leftKeys.every((key) => Object.hasOwn(rightRecord, key) && formValuesEqual(leftRecord[key], rightRecord[key]))
  );
}

export interface TanStackEngineProps {
  children: (engine: AutoFormEngine) => React.ReactNode;
  defaultValues: FormValues;
  formOptions?: TanStackFormOptions | undefined;
  onDirtyChange?: ((isDirty: boolean) => void) | undefined;
  values?: FormValues | undefined;
}

export function TanStackEngine({ children, defaultValues, formOptions, values, onDirtyChange }: TanStackEngineProps) {
  // allow: form-validate [AutoForm injects schema-provider validation through its engine]
  "use no memo";

  const submitRef = React.useRef<((values: FormValues) => void | Promise<void>) | undefined>(undefined);
  const nativeSubmissionRef = React.useRef<TanStackSubmitPayload | undefined>(undefined);
  const formDefaultValuesRef = React.useRef(defaultValues);
  const nativeOnSubmit = formOptions?.onSubmit;
  const form = useForm<
    FormValues,
    SyncValidator,
    SyncValidator,
    AsyncValidator,
    SyncValidator,
    AsyncValidator,
    SyncValidator,
    AsyncValidator,
    SyncValidator,
    AsyncValidator,
    AsyncValidator,
    unknown
  >({
    ...(formOptions ?? {}),
    defaultValues: formDefaultValuesRef.current,
    onSubmit: async (submission) => {
      nativeSubmissionRef.current = submission;
      await submitRef.current?.(submission.value);
    },
  });
  const state = useSelector(form.store, (current) => current);
  const cleanValuesRef = React.useRef<FormValues>(defaultValues);
  const [validationErrors, setValidationErrors] = React.useState<SchemaValidationError[]>([]);
  const [submitError, setSubmitError] = React.useState<string>();
  const fieldRefs = React.useRef(new Map<string, HTMLElement>());
  const fieldErrors = React.useMemo(() => validationErrorsByPath(validationErrors), [validationErrors]);
  const dirtyFields = dirtyFieldsFromMeta(state.fieldMeta);
  const isDirty = !formValuesEqual(state.values, cleanValuesRef.current);
  const notifyDirtyChange = useDirtyStateNotification(isDirty, onDirtyChange);
  const errors: Record<string, unknown> = {};
  for (const [path, meta] of Object.entries(state.fieldMeta)) {
    const messages = errorMessages(meta?.errors ?? []);
    if (messages.length > 0) {
      setErrorAtPath(errors, path.split("."), messages);
    }
  }
  for (const [path, messages] of fieldErrors) {
    setErrorAtPath(errors, path.split("."), messages);
  }
  const validationRootErrors: string[] = [];
  for (const error of validationErrors) {
    if (error.path.length === 0) {
      validationRootErrors.push(error.message);
    }
  }
  const nativeRootErrors = errorMessages(state.errors);
  const rootError =
    [...nativeRootErrors, ...validationRootErrors, ...(submitError ? [submitError] : [])].join("\n") || undefined;

  React.useEffect(() => {
    if (values) {
      formDefaultValuesRef.current = values;
      cleanValuesRef.current = values;
      form.reset(values);
      notifyDirtyChange(false);
    }
  }, [form, values, notifyDirtyChange]);

  const clearErrors = (paths?: string[]) => {
    setSubmitError(undefined);
    setValidationErrors((current) => {
      if (!paths) {
        return [];
      }
      const targets = new Set(paths);
      return current.filter((error) => !targets.has(error.path.join(".")));
    });
  };

  const clearFieldErrors = React.useCallback((name: string) => {
    setValidationErrors((current) => current.filter((error) => error.path.join(".") !== name));
  }, []);
  const registerRef = React.useCallback((name: string, element: HTMLElement | null) => {
    if (element) {
      fieldRefs.current.set(name, element);
    } else {
      fieldRefs.current.delete(name);
    }
  }, []);
  const contextValue = React.useMemo<TanStackEngineContextValue>(
    () => ({ clearFieldErrors, fieldErrors, form, registerRef }),
    [clearFieldErrors, fieldErrors, form, registerRef]
  );

  const engine: AutoFormEngine = {
    ArrayController: TanStackArrayController,
    clearErrors,
    defaultValues: cleanValuesRef.current,
    dirtyFields,
    errors,
    FieldController: TanStackFieldController,
    focus: (path) => fieldRefs.current.get(path)?.focus(),
    getFieldInvalid: (path) =>
      (state.fieldMeta[path]?.errors.length ?? 0) > 0 || (fieldErrors.get(path)?.length ?? 0) > 0,
    getValues: () => form.state.values,
    handleSubmit: (onValid) => (event) => {
      event.preventDefault();
      submitRef.current = onValid;
      Promise.resolve(form.handleSubmit()).catch((error: unknown) => {
        setSubmitError(error instanceof Error ? error.message : "Submission failed.");
      });
    },
    isDirty,
    isSubmitting: state.isSubmitting,
    markClean: () => {
      const currentValues = form.state.values;
      formDefaultValuesRef.current = currentValues;
      cleanValuesRef.current = currentValues;
      form.reset(currentValues);
      notifyDirtyChange(false);
    },
    nativeForm: form,
    reset: (nextValues, options) => {
      if (!options?.keepDefaultValues) {
        formDefaultValuesRef.current = nextValues;
        cleanValuesRef.current = nextValues;
      }
      form.reset(nextValues, options);
    },
    rootError,
    runNativeSubmit: nativeOnSubmit
      ? async () => {
          const submission = nativeSubmissionRef.current;
          if (submission) {
            await nativeOnSubmit(submission);
          }
        }
      : undefined,
    setRootError: setSubmitError,
    setValidationErrors,
    setValue: (path, value, options) => {
      setValidationErrors((current) => current.filter((error) => error.path.join(".") !== path));
      form.setFieldValue(path, value, {
        dontUpdateMeta: options?.shouldDirty === false && options.shouldTouch === false,
        dontValidate: options?.shouldValidate === false,
      });
    },
    trigger: async (paths) => {
      const results = paths
        ? await Promise.all(paths.map((path) => form.validateField(path, "submit")))
        : await form.validateAllFields("submit");
      return results.flat().length === 0;
    },
    validatesSchema: false,
    values: state.values,
  };

  return (
    <TanStackEngineContext.Provider value={contextValue}>
      <AutoFormEngineProvider engine={engine}>{children(engine)}</AutoFormEngineProvider>
    </TanStackEngineContext.Provider>
  );
}
